(function(){
  const N = 70;
  const particles = [];
  for(let i=0;i<N;i++){
    const edge = Math.random();
    let x,y;
    if(edge<0.55){
      x = Math.random()*W();
      y = Math.random()<0.5 ? Math.random()*H()*0.26 : H()*0.74+Math.random()*H()*0.26;
    } else {
      y = Math.random()*H();
      x = Math.random()<0.5 ? Math.random()*W()*0.20 : W()*0.80+Math.random()*W()*0.20;
    }
    particles.push({
      baseX:x, baseY:y,
      r: 1+Math.random()*2.4,
      phase: Math.random()*Math.PI*2,
      speed: 0.12+Math.random()*0.22,
      amp: 8+Math.random()*18,
      color: PALETTE[Math.floor(Math.random()*PALETTE.length)],
      driftSpeed: 6+Math.random()*10
    });
  }

  function ribbon(t, yBase, dir, col){
    ctx.beginPath();
    ctx.globalAlpha = 0.14;
    ctx.strokeStyle = col;
    ctx.lineWidth = 1.2;
    const w = W();
    const steps = 40;
    for(let i=0;i<=steps;i++){
      const px = (i/steps)*w*0.32 + (dir>0?0:w*0.68);
      const py = yBase + Math.sin(t*0.4 + i*0.35)*10;
      if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
    }
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  let t=0;
  function frame(){
    t+=0.012;
    ctx.clearRect(0,0,W(),H());

    ribbon(t, H()*0.14, 1, PALETTE[1]);
    ribbon(t+1.3, H()*0.18, -1, PALETTE[0]);
    ribbon(t+0.6, H()*0.86, 1, PALETTE[0]);
    ribbon(t+2.1, H()*0.90, -1, PALETTE[1]);

    for(const p of particles){
      const dx = Math.sin(t*p.speed+p.phase)*p.amp;
      let py = p.baseY - ((t*p.driftSpeed + p.phase*10) % (H()*1.4)) + H()*0.2;
      py = ((py % H()) + H()) % H();
      const px = p.baseX+dx;
      const alpha = 0.3+0.3*Math.sin(t*p.speed*1.4+p.phase);
      ctx.beginPath();
      ctx.globalAlpha = Math.max(0.05,alpha);
      ctx.shadowBlur = 9;
      ctx.shadowColor = p.color;
      ctx.fillStyle = p.color;
      ctx.arc(px,py,p.r,0,Math.PI*2);
      ctx.fill();
    }
    ctx.globalAlpha=1;
    ctx.shadowBlur=0;
    requestAnimationFrame(frame);
  }
  frame();
})();
